 "content": "def transform(grid):
    """Complete a periodic diagonal color field from colored diagonal clues."""
    h, w = len(grid), len(grid[0])
    candidates = []
    for kind in ("sum", "diff"):
        lines = {}
        for r in range(h):
            for c in range(w):
                color = grid[r][c]
                if color:
                    k = r + c if kind == "sum" else c - r
                    lines.setdefault(k, []).append((r, c, color))
        # Clue strokes are diagonal and each stroke has one color. Prefer the
        # orientation accounting for the greatest number of multi-cell clues.
        supported = {k: cells for k, cells in lines.items()
                     if len(cells) >= 2 and len({x[2] for x in cells}) == 1}
        covered = sum(len(cells) for cells in supported.values())
        candidates.append((covered, kind, supported))
    _, kind, lines = max(candidates, key=lambda x: x[0])
    clues = {k: cells[0][2] for k, cells in lines.items()}
    if not clues:
        raise ValueError("no diagonal clue lines found")

    # The encoded period is the smallest fully specified residue cycle with
    # no conflicting colors assigned to a residue.
    period = None
    residue_colors = None
    for p in range(2, max(h, w) + 1):
        mapping = {}
        valid = True
        for k, color in clues.items():
            residue = k % p
            if residue in mapping and mapping[residue] != color:
                valid = False
                break
            mapping[residue] = color
        if valid and len(mapping) == p:
            period, residue_colors = p, mapping
            break
    if period is None:
        raise ValueError("diagonal clues do not determine a complete period")
    return [[residue_colors[(r + c if kind == "sum" else c - r) % period]
             for c in range(w)] for r in range(h)]


