    """Extend colored constant-sum diagonal clues as a periodic field."""
    h, w = len(grid), len(grid[0])
    clues = {}
    for r, row in enumerate(grid):
        for c, color in enumerate(row):
            if color:
                clues.setdefault(r + c, []).append(color)
    # Every encoded diagonal has a consistent color; repeated colors at
    # separated offsets identify the cycle length.
    colors = {k: vals[0] for k, vals in clues.items()
              if len(set(vals)) == 1}
    repeated_gaps = [b-a for a, ca in colors.items()
                     for b, cb in colors.items() if b > a and ca == cb]
    period = min(repeated_gaps) if repeated_gaps else len(colors)
    if period < 2:
        period = 2
    residues = {}
    for k, color in colors.items():
        residues[k % period] = color
    # Fill unmarked phases by extending the nearest known phase cyclically.
    known = sorted(residues)
    if not known:
        raise ValueError("no consistent diagonal clues")
    for q in range(period):
        if q not in residues:
            nearest = min(known, key=lambda x: (min((q-x) % period,
                                                     (x-q) % period), x))
            residues[q] = residues[nearest]
    return [[residues[(r+c) % period] for c in range(w)] for r in range(h)]


